                html.append("&amp;lsquo;"); // Кавычка левая (&lsquo;)
                break;
            case '`':
                html.append("&amp;rsquo;"); // Кавычка правая (&rsquo;)
                break;
            case '[':
                html.append("&amp;lcub;"); // Фигурная скобка левая (&lcub;)
                break;
            case ']':
                html.append("&amp;rcub;"); // Фигурная скобка правая (&rcub;)
                break;
            case '{':
                html.append("&amp;lbrack;"); // Скобка фигурная левая (&lbrack;)
                break;
            case '}':
                html.append("&amp;rbrack;"); // Скобка фигурная правая (&rbrack;)
                break;
            default:
                html.push_back(c); // Добавить символ в HTML-строку, если он не является символом уменьшения размера шрифта
        }
    }

    return html;
}

